create temporary view search_be_log as
    select /*+REPARTITION(1000)*/
          get_json_object(`value`, '$.request.header.request_id') as request_id
         ,get_json_object(`value`, '$.request.header.session_id') as session_id
         ,get_json_object(`value`, '$.response.header.search_session_id') as search_session_id_be
         ,cast(get_json_object(`value`, '$.timestamp') as bigint) as backend_log_timestamp
         ,get_json_object(get_json_object(`value`,'$.request.extra_param'),'$.global_search_session_id') as global_session_id
         ,get_json_object(get_json_object(`value`,'$.request.extra_param'),'$.search_session_id') as search_session_id
         ,from_json(get_json_object(`value`, '$.response.ab_sign'), 'ARRAY<int>') as ab_sign
         ,from_json(get_json_object(`value`, '$.response.item'), 'ARRAY<string>') as items
         ,upper(get_json_object(`value`, '$.request.header.country')) as grass_region
         ,cast(get_json_object(`value`, '$.request.header.user_id') as bigint) as user_id
         ,get_json_object(`value`, '$.response.query_rewrite.rewrite_keywords') as rewrite_keyword
         ,get_json_object(`value`, '$.response.query_rewrite.ori_keyword') as ori_keyword
         ,cast(get_json_object(`value`, '$.response.query_rewrite.ori_total_count') as bigint) as ori_total_count
         ,cast(get_json_object(`value`, '$.response.query_rewrite.rewrite_type') as int) as rewrite_type
         ,cast(get_json_object(`value`, '$.response.total_count') as bigint) as total_count
         ,NAMED_STRUCT(
                      'expansion_type',
                       CAST(get_json_object(`value`, '$.response.query_expansion_info.expansion_type') AS INT),
                      'expansion_keyword',
                       from_json(get_json_object(`value`, '$.response.query_expansion_info.expansion_keyword'), 'ARRAY<STRING>')
                     ) AS query_expansion_info
         ,cast(get_json_object(`value`, '$.response.downstream') as string) as downstream
         ,get_json_object(`value`, '$.request.keyword') as request_keyword
         ,get_json_object(`value`, '$.request.sorttype') as request_sort_type
         ,get_json_object(`value`, '$.response.mix_rank_model_type') as mix_rank_model_type
         ,cast(get_json_object(`value`, '$.request.offset') AS INT) as offset
         ,get_json_object(`value`, '$.request.extra_param.is_nls_consult') as is_nls_consult
         ,get_json_object(`value`, '$.response.downstream.qp_logs.price_filter_flag') as price_filter_flag
         ,get_json_object(`value`, '$.response.request_level_mix_params') as request_level_mix_params
         ,get_json_object(`value`, '$.response.multimodal_info.multimodal_user_intention_info') as multimodal_user_intention_info
         ,get_json_object(`value`, '$.response.multimodal_info.filter_groups') as multimodal_info_filter_groups
         ,cast(get_json_object(`value`, '$.response.multimodal_info.sort_type') as int) as multimodal_info_sort_type
         ,cast(get_json_object(`value`, '$.response.multimodal_info.fallback_to_image_search') as boolean) as multimodal_info_fallback_to_image_search

         ,cast(get_json_object(`value` , '$.response.other_info.filter_intention_data.disabled') as boolean) as flt_intent_disabled
         ,from_json(get_json_object(`value` , '$.response.other_info.filter_intention_data.filter_list'), 'ARRAY<STRING>') as flt_intent_filter_list
         ,get_json_object(`value` , '$.response.other_info.filter_intention_data.new_query') as flt_intent_new_query
         ,get_json_object(`value` , '$.response.other_info.filter_intention_data.raw_query') as flt_intent_raw_query
         ,get_json_object(`value` , '$.response.multimodal_info.multimodal_origin_keyword') as multimodal_origin_keyword
         ,get_json_object(get_json_object(`value`, '$.response.multimodal_info.algo_data'),'$.search_text') as multimodal_intention_model_search_text
         ,get_json_object(value,'$.search_page') AS search_page
         ,get_json_object(value, '$.request.extra_param.chat_conversation_id') AS chatgpt_conversation_id
         ,get_json_object(value, '$.request.extra_param.intent_type') AS chatgpt_intent_type
         ,get_json_object(value, '$.request.extra_param.original_prompt') AS chatgpt_original_prompt
         ,get_json_object(value, '$.request.extra_param.search_query') AS chatgpt_search_query
         ,get_json_object(value, '$.request.extra_param.search_query_trans') AS chatgpt_search_query_trans
         ,cast(get_json_object(value, '$.request.extra_param.receive_request_time') as bigint) AS receive_request_time
        ,dt
        ,hh
    from search_data.ods_search_intel_log_v2_1h_raw
    where dt = ${regional_date} and hh = ${regional_hour}
    and upper(get_json_object(`value`,'$.request.header.country')) in ('TW','CL','MX','MY','CO','BR','SG','TH','PH','VN','ID','AR', 'KH','MM','LA');

