create temporary view search_be_log_exploded as
select
     request_id
    ,backend_log_timestamp
    ,global_session_id
    ,search_session_id
    ,cast(get_json_object(item,'$.item_id') as bigint) as item_id
    ,cast(get_json_object(item, '$.shop_id') AS BIGINT)  as shop_id
    ,cast(get_json_object(item,'$.downstream.Rank.rule_id') as bigint) as tc_rule_id
    ,get_json_object(item,'$.downstream.Rank.item_group_id') as tc_item_group_id
    ,user_id
    ,get_json_object(item, '$.downstream.Rank.boost_weight') as tc_boost_weight
    ,ab_sign
    ,cast(get_json_object(item,'$.ad_info.ads_id') as bigint) as ads_id
    ,from_json(get_json_object(get_json_object(item, '$.downstream.dynamic_ui'), '$.label_text'), 'ARRAY<string>') as label_text
    ,from_json(get_json_object(get_json_object(item, '$.downstream.dynamic_ui'), '$.label_name'), 'ARRAY<string>') as label_name
    ,cast(get_json_object(get_json_object(item, '$.downstream.Rank'), '$.rel_add') as double) as rel_add
    ,cast(get_json_object(get_json_object(item, '$.downstream.Rank'), '$.rel_lx') as int) as rel_lx
    ,cast(get_json_object(get_json_object(item, '$.downstream.Rank'), '$.rel_raw') as double) as rel_raw
    ,cast(get_json_object(item, '$.recall_score') as double) as es_score
    ,cast(get_json_object(item, '$.recall_rank') as int) as recall_rank
    ,cast(get_json_object(item, '$.merge_rank') as int) as merge_rank
    ,cast(get_json_object(item, '$.rank_score') as double) as rank_score
    ,cast(get_json_object(item, '$.rank_rank') as int) as rank_rank
    ,rewrite_keyword
    ,ori_keyword
    ,ori_total_count
    ,rewrite_type
    ,total_count
    ,query_expansion_info
    ,cast(get_json_object(get_json_object(item, '$.refreshing_info'),'$.item_id') as bigint) as refreshed_item_id
    ,cast(get_json_object(get_json_object(item, '$.refreshing_info'),'$.position') as int) as refreshed_item_position
    ,NAMED_STRUCT(
                  'rule_ids',
                  from_json(get_json_object(item, '$.rule_ids'), 'ARRAY<int>'),
                  'matched_keywords',
                  from_json(get_json_object(item, '$.matched_keywords'), 'ARRAY<string>')
                  ) as recall_item_tracking_info
    ,downstream
    ,cast(get_json_object(item, '$.item_type') as int) as card_type
    ,get_json_object(item, '$.downstream.dynamic_ui') AS dynamic_ui
    ,session_id
    ,search_session_id_be
    ,request_keyword
    ,request_sort_type
    ,cast(get_json_object(item, '$.video.video_id') as bigint) AS video_id
    ,cast(get_json_object(item, '$.live.intention_type') as int) AS live_intention_type
    ,cast(get_json_object(item, '$.live.session_id') as bigint) AS live_session_id
    ,cast(get_json_object(item, '$.live.relevance_score') as int) AS live_relevance_score
    ,cast(get_json_object(item, '$.live.biz_value_score') as double) AS live_biz_value_score
    ,cast(get_json_object(item, '$.live.ctcvr_score') as double) AS live_ctcvr_score
    ,cast(get_json_object(item, '$.ctr_score') as double) AS ctr_score
    ,cast(get_json_object(item, '$.cvr_score') as double) AS cvr_score
    ,cast(get_json_object(item, '$.rel_lx_score') as int) AS rel_lx_score
    ,get_json_object(item, '$.related_card') AS related_card
    ,from_json(get_json_object(item, '$.rule_ids'),'ARRAY<int>') AS rule_ids
    ,cast(get_json_object(item, '$.roi2.ads_id') as bigint) AS ads_id_for_roi2
    ,cast(get_json_object(item, '$.roi2.pctr') as double)  AS pctr_for_roi2
    ,cast(get_json_object(item, '$.roi2.pcr') as double)  AS pcr_for_roi2
    ,cast(get_json_object(item, '$.roi2.broad_pcr') as double)  AS broad_pcr_for_roi2
    ,cast(get_json_object(item, '$.roi2.roi2_rank_score') as double) AS roi2_rank_score_for_roi2
    ,cast(get_json_object(item, '$.roi2.roi2_rank_rank') as int) AS roi2_rank_rank_for_roi2
    ,cast(get_json_object(item, '$.roi2.porg') as double) AS porg_for_roi2
    ,cast(get_json_object(item, '$.roi2.ecpm') as double) AS ecpm_for_roi2
    ,cast(get_json_object(item, '$.roi2.ecpm_weight') as double) AS ecpm_weight_for_roi2
    ,cast(get_json_object(item, '$.ads_mix_rank_score') as double) AS ads_mix_rank_score
    ,location
    ,cast(get_json_object(item, '$.ad.pctr') as double) AS pctr_for_roi1
    ,cast(get_json_object(item, '$.ad.pcr') as double) AS pcr_for_roi1
    ,from_json(get_json_object(item, '$.real_item_type_list'), 'ARRAY<string>') AS real_item_type_list
    ,get_json_object(item, '$.imp_item_type') AS imp_item_type
    ,cast(get_json_object(item, '$.ads_mix_params.model_pid') as double) AS model_pid
    ,mix_rank_model_type
    ,cast(get_json_object(item, '$.ads_mix_params.mix_rank_model_score') as double) AS mix_rank_model_score
    ,cast(get_json_object(item, '$.ad.mock_deduction_price') as bigint) AS mock_deduction_price
    ,get_json_object(item, '$.ads_mix_params') AS ads_mix_params
    ,offset
    ,is_nls_consult
    ,price_filter_flag
    ,cast(get_json_object(item, '$.mix_score') as double) AS mix_score
    ,request_level_mix_params
    ,multimodal_user_intention_info
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.edt_max') AS INT) AS edt_max
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.edt_max_hours') AS INT) AS edt_max_hours
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.edt_min') AS INT) AS edt_min
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.edt_min_hours') AS INT) AS edt_min_hours
    ,get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.estimated_delivery_time_text') AS estimated_delivery_time_text
    ,from_json(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.fastest_channel_ids'), 'ARRAY<BIGINT>') AS fastest_channel_ids
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.max_estimated_delivery_timestamp') AS INT) AS max_estimated_delivery_timestamp
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.min_estimated_delivery_timestamp') AS INT) AS min_estimated_delivery_timestamp
    ,cast(get_json_object(item, '$.ocpc_item.ads_id') AS INT) AS ads_id_for_ocpc
    ,cast(get_json_object(item, '$.replaced_item_id') as bigint) as replaced_item_id
    ,get_json_object(item, '$.has_replacement_candidate') as has_replacement_candidate
    ,get_json_object(item, '$.eligible_to_replace') as eligible_to_replace
    ,get_json_object(item, '$.cheapest_replacement') as cheapest_replacement
    ,cast(get_json_object(item, '$.ritem_id') AS BIGINT)  as ritem_id
    ,cast(get_json_object(item, '$.rshop_id') AS BIGINT)  as rshop_id
    ,cast(get_json_object(item, '$.rmodel_id') AS BIGINT)  as rmodel_id
    ,cast(get_json_object(item, '$.vmodel_id') AS BIGINT)  as vmodel_id
    ,multimodal_info_filter_groups
    ,multimodal_info_sort_type
    ,multimodal_info_fallback_to_image_search
    ,cast(get_json_object(item, '$.rel_raw_score') as double) as rel_raw_score
    ,flt_intent_disabled
    ,flt_intent_filter_list
    ,flt_intent_new_query
    ,flt_intent_raw_query
    ,from_json(get_json_object(item, '$.effective_rule_ids'), 'ARRAY<INT>') AS effective_rule_ids
    ,multimodal_origin_keyword
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.calc_edt_max_hours') AS INT) AS calc_edt_max_hours
    ,cast(get_json_object(get_json_object(item, '$.estimated_delivery_time'), '$.calc_edt_max') AS INT) AS calc_edt_max
    ,get_json_object(item, '$.ad_info') as ad_info
    ,CAST(get_json_object(item, '$.ctx_item_type') AS INT) as ctx_item_type
    ,get_json_object(item, '$.item_unique_key') as item_unique_key
    ,multimodal_intention_model_search_text
    ,search_page
    ,chatgpt_conversation_id
    ,chatgpt_intent_type
    ,chatgpt_original_prompt
    ,chatgpt_search_query
    ,chatgpt_search_query_trans
    ,receive_request_time
    ,cast(get_json_object(item,'$.estimated_delivery_time.filtered_by_unserviceable') AS BOOLEAN) AS filtered_by_unserviceable
    ,cast(get_json_object(item, '$.estimated_delivery_time.edt_min_mins') AS INT) AS edt_min_mins
    ,cast(get_json_object(item,'$.estimated_delivery_time.edt_max_mins') AS INT) AS edt_max_mins
    ,from_json(get_json_object(item, '$.item_identities'), 'ARRAY<STRING>') AS biz_flag
    ,from_json(get_json_object(item, '$.tc_rule_array'), 'ARRAY<STRING>') AS tc_rule_array
    ,get_json_object(item, '$.vitem_replacement') AS vitem_replacement
    ,get_json_object(item, '$.vitem_info') AS vitem_info

    ,grass_region
    ,date(date_timezone_convert(dt,hh,'SG',grass_region,"yyyy-MM-dd")) as local_date
    ,cast(date_timezone_convert(dt,hh,'SG',grass_region,"HH") as int) as local_hour
    ,cast(dt as date) as regional_date
    ,cast(hh as int) as regional_hour
from search_be_log
lateral view posexplode(items) exploded_items as location, item;

